(()=>{const d=/^(\d{4})-(0[1-9]|1[0-2])$/,c=t=>{const e=d.exec(t);return e?{year:Number(e[1]),month:Number(e[2])}:null};document.querySelectorAll(".experience-date[data-start][data-end]").forEach(t=>{const e=c(t.dataset.start),a=t.dataset.end==="now",n=a?{year:new Date().getUTCFullYear(),month:new Date().getUTCMonth()+1}:c(t.dataset.end);if(!e||!n)return;const h=(n.year-e.year)*12+n.month-e.month;if(h<0)return;const r=h+1,o=Math.floor(r/12),u=r%12,y=o>0?`${o}${a||u>0?"+":""} ${o===1?"Year":"Years"}`:`${r} ${r===1?"Month":"Months"}`,s=e.year,l=a?`${s} - Present`:e.year===n.year?s:`${s} - ${n.year}`;t.querySelector(".experience-range").textContent=l,t.querySelector(".experience-duration").textContent=`\u2022 ${y}`})})();
